use axum::extract::State;
use axum::Json;
use serde::{Deserialize, Serialize};
use sqlx::{PgPool, Row};

use crate::error::AppError;
use crate::password;

pub struct Account {
    pub id: i64,
    pub email: String,
    pub password_hash: String,
}

#[derive(Deserialize)]
pub struct LoginForm {
    pub email: String,
    pub password: String,
}

#[derive(Serialize)]
pub struct LoginResponse {
    pub id: i64,
}

pub async fn find_by_email(pool: &PgPool, email: &str) -> Result<Account, sqlx::Error> {
    let row = sqlx::query("SELECT id, email, password_hash FROM accounts WHERE email = $1")
        .bind(email)
        .fetch_one(pool)
        .await?;
    Ok(Account {
        id: row.get("id"),
        email: row.get("email"),
        password_hash: row.get("password_hash"),
    })
}

pub async fn login(
    State(pool): State<PgPool>,
    Json(form): Json<LoginForm>,
) -> Result<Json<LoginResponse>, AppError> {
    let account = find_by_email(&pool, &form.email).await?;
    if !password::verify(&form.password, &account.password_hash) {
        return Err(AppError::Unauthorized);
    }
    Ok(Json(LoginResponse { id: account.id }))
}

